*{box-sizing:border-box} :root{color-scheme:dark;--ink:#f3f1ff;--muted:#87869f;--violet:#9d6dff;--cyan:#54f4e3;--red:#ff466c;font-family:'Space Grotesk',sans-serif} html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#080812;color:var(--ink)} body{min-height:100dvh;user-select:none;-webkit-tap-highlight-color:transparent}.game-shell{position:relative;width:100%;height:100dvh;min-height:480px;overflow:hidden;background:#090914;isolation:isolate}canvas{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:manipulation}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(8,8,18,.55),transparent 68%),linear-gradient(0deg,rgba(7,7,17,.67),transparent 34%,rgba(7,7,17,.3));z-index:1}.topbar{position:absolute;z-index:4;left:0;right:0;top:0;padding:26px 5.2%;display:flex;align-items:center;justify-content:space-between}.wordmark{text-decoration:none;color:#f5f2ff;font-size:15px;font-weight:700;letter-spacing:.13em}.brand-mark{color:var(--cyan);font-size:20px;vertical-align:-2px;margin-right:8px}.brand-run{color:var(--cyan)}.top-actions{display:flex;align-items:center;gap:14px}.currency{height:36px;padding:0 12px;border:1px solid rgba(183,153,255,.25);border-radius:20px;background:rgba(22,20,39,.72);display:flex;align-items:center;gap:8px;font:12px 'DM Mono',monospace}.orb-icon{color:#d2a3ff;font-size:17px}.icon-button{width:38px;height:38px;border:1px solid rgba(222,213,255,.18);border-radius:50%;background:rgba(15,14,30,.6);color:#e9e2ff;font-size:19px;cursor:pointer;transition:.2s}.icon-button:hover{border-color:var(--cyan);color:var(--cyan)}.screen{position:absolute;z-index:3;inset:0}.hidden{display:none!important}.menu-copy{position:absolute;top:49%;left:10.4%;transform:translateY(-42%);max-width:530px}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:.2em;color:#9b98b4}.intro-label{display:flex;align-items:center;gap:9px;margin-bottom:19px}.live-dot{width:6px;height:6px;display:inline-block;background:var(--cyan);border-radius:50%;box-shadow:0 0 11px var(--cyan)}h1{font-size:clamp(54px,8.5vw,110px);line-height:.83;letter-spacing:-.075em;margin:0;font-weight:700;color:#f3f0ff;text-shadow:0 4px 34px rgba(151,95,255,.12)}h1>span:first-of-type{color:transparent;-webkit-text-stroke:1px rgba(215,204,255,.72)}.period{color:var(--cyan)}.tagline{font-size:15px;color:#aca8c1;margin:22px 0 26px;letter-spacing:.02em}.primary-button{position:relative;display:flex;align-items:center;justify-content:space-between;width:220px;height:54px;padding:0 18px;border:0;border-radius:4px;background:linear-gradient(105deg,#d9c5ff,#a991ff 60%,#8d70ff);color:#171124;font:700 12px 'Space Grotesk',sans-serif;letter-spacing:.12em;cursor:pointer;box-shadow:0 0 34px rgba(155,113,255,.21);transition:transform .18s,box-shadow .18s}.primary-button:hover{transform:translateY(-2px);box-shadow:0 0 42px rgba(155,113,255,.42)}.primary-button b{font-size:19px;font-weight:400}.control-note{display:flex;align-items:center;gap:10px;margin-top:16px;color:#85829d;font:10px 'DM Mono',monospace}.keycap{border:1px solid #49445f;border-radius:3px;padding:4px 6px;color:#d9d3ef;font-size:9px;letter-spacing:.12em}.note-divider{color:#48455d}.menu-bottom{position:absolute;left:5.2%;right:5.2%;bottom:27px;display:flex;justify-content:space-between;color:#77748d;font:9px 'DM Mono',monospace;letter-spacing:.15em}.menu-bottom b{color:#d2cae8;font-weight:400;margin-left:12px}.skin-entry{position:absolute;right:5.2%;bottom:63px;background:rgba(16,14,31,.7);border:1px solid rgba(198,180,255,.2);padding:11px 14px;color:#c5bfd9;font:9px 'DM Mono',monospace;letter-spacing:.12em;border-radius:3px;cursor:pointer}.skin-entry:hover{border-color:var(--violet)}.skin-spark{color:var(--cyan);margin-right:7px}.arrow{margin-left:10px;color:#9186b4}.hud{position:absolute;z-index:4;left:5.2%;right:5.2%;top:92px;pointer-events:none}.hud-score{display:flex;flex-direction:column;gap:2px}.hud-score strong{font:28px 'DM Mono',mo