argin:24px auto 20px;display:flex;align-items:center;justify-content:center;overflow:hidden;background:radial-gradient(ellipse at center,rgba(127,83,234,.18),transparent 63%);border-bottom:1px solid rgba(188,166,255,.12)}.preview-orbit{position:absolute;width:135px;height:135px;border:1px solid rgba(115,91,178,.3);border-radius:50%;box-shadow:0 0 36px rgba(133,77,255,.12)}.preview-shadow{position:relative;width:39px;height:46px;background:#d6b7ff;border-radius:48% 48% 40% 40%;box-shadow:0 0 22px #a46aff,0 0 60px #7f39ff;animation:floaty 2s ease-in-out infinite}.preview-shadow:after{content:'';position:absolute;top:13px;left:8px;width:5px;height:3px;background:#fff;border-radius:50%;box-shadow:15px 0 #fff,0 0 8px white,15px 0 8px white}.preview-label{position:absolute;bottom:10px;font:9px 'DM Mono',monospace;letter-spacing:.17em;color:#ded3fa}.preview-label span{color:#9089a5}.skin-list{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.skin-card{min-height:74px;padding:9px 5px;background:rgba(255,255,255,.025);border:1px solid rgba(191,174,230,.14);color:#dad4e9;text-align:center;cursor:pointer;border-radius:3px}.skin-card.selected{border-color:var(--cyan);background:rgba(84,244,227,.06)}.skin-swatch{display:block;width:17px;height:17px;margin:0 auto 7px;border-radius:50%;box-shadow:0 0 13px currentColor}.skin-name{font:8px 'DM Mono',monospace;letter-spacing:.1em;display:block}.skin-cost{font:8px 'DM Mono',monospace;color:#9992ab;display:block;margin-top:4px}.garage-footer{position:absolute;bottom:25px;left:10%;right:10%;display:flex;justify-content:space-between;color:#8f8aa2;font:9px 'DM Mono',monospace;letter-spacing:.15em}.garage-footer b{color:#dfc4ff;font-size:12px}.toast{position:absolute;z-index:8;left:50%;bottom:26%;transform:translateX(-50%);padding:10px 15px;background:#171328;border:1px solid #59467e;color:#ded5f7;font:11px 'DM Mono',monospace;white-space:nowrap;box-shadow:0 8px 30px #0009}.flash{position:absolute;inset:0;z-index:5;pointer-events:none;background:rgba(255,50,87,0);transition:background .08s}.flash.hit{background:rgba(255,39,88,.23)}@keyframes floaty{50%{transform:translateY(-8px)}}
