  for(let i=0;i<5;i++){const x=(i*W/4-(t*45)% (W/4)+W/4)%(W+20);ctx.fillStyle=`rgba(92,244,227,${.22+.2*Math.sin(t*3+i)})`;ctx.fillRect(x,top+2,2,3);ctx.fillRect(x,bottom-5,2,3);}
