    if(state==='menu' || state==='over') { player.x=W*(W<600?.24:.255); player.y=laneY(1)+Math.sin(t*2.7)*3; }
    const tint=color(), lane=player.lane;ctx.save();ctx.translate(player.x,player.y);if(lane===0)ctx.rotate(Math.PI);
